mapper.insert:
INSERT INTO ticket_validation_logs (
    issued_ticket_id, validator_user_id, presented_token_fingerprint,
    validation_result, validation_channel, device_id, failure_reason
) VALUES (
    #{issuedTicketId}, #{validatorUserId}, #{fingerprint},
    #{result}, #{channel}, #{deviceId}, #{failureReason}
)

mapper.select:
SELECT l.ticket_validation_log_id, l.issued_ticket_id, t.ticket_number, ri.product_name, l.validator_user_id, u.nickname AS validator_nickname, l.validation_result, l.validation_channel, l.failure_reason, l.validated_at FROM ticket_validation_logs l LEFT JOIN issued_tickets t ON t.issued_ticket_id = l.issued_ticket_id LEFT JOIN reservation_items ri ON ri.reservation_item_id = t.reservation_item_id LEFT JOIN users u ON u.user_id = l.validator_user_id
AND l.validation_result = #{result}
ORDER BY l.validated_at DESC, l.ticket_validation_log_id DESC LIMIT #{limit}
